from typing import Iterator, Tuple
Position = Tuple[int, int]
def options(p: Position) -> Iterator[Position]:
    m, n = p
    yield from ((k, n) for k in range(m))
    yield from ((m, k) for k in range(n))
@lru_cache(None)
def winning(p: Position) -> bool:
    return any(not winning(q) for q in options(p))
def main(limit: int = 10) -> None:
    for m in range(limit + 1):
        print(" ".join("W" if winning((m, n)) else "L" for n in range(limit + 1)))
    assert all(winning((m, n)) == (m != n) for m in range(limit + 1) for n in range(limit + 1))
if __name__ == "__main__": main()

from __future__ import annotations
from typing import List, Sequence, Tuple
Position = Tuple[int, int]
Opening = Tuple[str, int]
def play(start: int, openings: Sequence[Opening]) -> List[Position]:
    state = (start, start); path = [state]
    for side, target in openings:
        if not 0 <= target < state[0]: raise ValueError("illegal decrease")
        opened = (target, state[1]) if side.upper() == "L" else (state[0], target)
        path.extend([opened, (target, target)]); state = (target, target)
    return path
def main() -> None:
    print(" -> ".join(map(str, play(12, [("L", 9), ("R", 5), ("L", 2), ("R", 0)]))))
if __name__ == "__main__": main()

from __future__ import annotations
def two_heap_winning(m: int, n: int) -> bool:
    if m < 0 or n < 0: raise ValueError("heap sizes must be nonnegative")
    return m != n
def main() -> None:
    print({"1 alone wins": two_heap_winning(1, 0), "(1,1) wins": two_heap_winning(1, 1)})
    print({"0 alone loses": not two_heap_winning(0, 0), "(0,1) wins": two_heap_winning(0, 1)})
if __name__ == "__main__": main()

