from __future__ import annotations
from functools import lru_cache
from typing import Dict, Iterable, Tuple
Node = str
Graph = Dict[Node, Tuple[Node, ...]]
def solve(graph: Graph, start: Node) -> bool:
    visiting: set[Node] = set()
    @lru_cache(None)
    def win(node: Node) -> bool:
        if node in visiting: raise ValueError("graph is not well-founded")
        visiting.add(node)
        result = any(not win(child) for child in graph.get(node, ()))
        visiting.remove(node)
        return result
    return win(start)

from __future__ import annotations
from typing import Optional, Tuple
Position = Tuple[int, int]
def optimal_countdown_move(position: Position) -> Optional[Position]:
    m, n = position
    if m < 0 or n < 0: raise ValueError("heap sizes must be nonnegative")
    if m == n: return None
    k = min(m, n)
    return (k, k)

from __future__ import annotations
from typing import Tuple
Position = Tuple[int, int]
def mirror(before: Position, opening: Position) -> Position:
    a, b = before; x, y = opening
    if a != b: raise ValueError("before must be diagonal")
    if x < a and y == b: return (x, x)
    if y < b and x == a: return (y, y)
    raise ValueError("opening must change exactly one component")

